// The reel: a dusk field behind a framed window; inside it, painted leather puppets pressed to a lamp-lit cloth.
window.W = {
  RIG: {},
  O: 'stroke:var(--ink);stroke-width:4;stroke-linejoin:round',
  // A row of punched holes along a line, the lace that lets the lamp through the leather.
  lace(x1, y1, x2, y2, n, r) {
    let s = '';
    for (let i = 0; i <= n; i++) { const k = i / n; s += '<circle cx="' + (x1 + (x2 - x1) * k).toFixed(1) + '" cy="' + (y1 + (y2 - y1) * k).toFixed(1) + '" r="' + r + '" style="fill:var(--lace)"/>'; }
    return s;
  },
  // The dusk field behind the window: sky, a low sun, dry grass and far trees.
  frame(kit, id) {
    const r = kit.rng(7); let grass = '', trees = '';
    for (let i = 0; i < 64; i++) {
      const x = r() * 1100 - 10, h = 90 + r() * 300, lean = (r() - 0.5) * 70, w = (2 + r() * 4).toFixed(1);
      grass += '<path d="M' + x.toFixed(0) + ' 1925 Q' + (x + lean * 0.4).toFixed(0) + ' ' + (1925 - h * 0.6).toFixed(0) + ' ' + (x + lean).toFixed(0) + ' ' + (1925 - h).toFixed(0) + '" style="fill:none;stroke:var(--grass);stroke-width:' + w + ';stroke-linecap:round"/>';
      if (i % 4 === 0) grass += '<ellipse cx="' + (x + lean).toFixed(0) + '" cy="' + (1925 - h).toFixed(0) + '" rx="5" ry="14" transform="rotate(' + (lean / 3).toFixed(0) + ' ' + (x + lean).toFixed(0) + ' ' + (1925 - h).toFixed(0) + ')" style="fill:var(--grass)"/>';
    }
    for (const [x, s] of [[150, 1], [420, 0.7], [880, 1.2]]) trees += '<g transform="translate(' + x + ' 1468) scale(' + s + ')" style="fill:color-mix(in srgb, var(--grass) 75%, var(--sky))"><rect x="-5" y="-70" width="10" height="70"/><ellipse cx="0" cy="-82" rx="78" ry="20"/><ellipse cx="-30" cy="-96" rx="40" ry="12"/><ellipse cx="34" cy="-94" rx="44" ry="13"/></g>';
    return '<svg class="art ' + id + '-field" viewBox="0 0 1080 1920"><defs><linearGradient id="' + id + '-sky" x1="0" y1="0" x2="0" y2="1"><stop offset="0" style="stop-color:var(--dusk)"/><stop offset=".42" style="stop-color:var(--sky)"/><stop offset=".74" style="stop-color:var(--gold)"/><stop offset="1" style="stop-color:var(--field)"/></linearGradient><radialGradient id="' + id + '-sun"><stop offset="0" style="stop-color:var(--second)"/><stop offset=".35" style="stop-color:var(--gold)"/><stop offset="1" style="stop-color:var(--main);stop-opacity:0"/></radialGradient></defs>' +
      '<rect width="1080" height="1920" fill="url(#' + id + '-sky)"/><circle class="' + id + '-sun" cx="780" cy="1430" r="460" fill="url(#' + id + '-sun)"/>' + trees +
      '<path d="M0 1470 Q320 1430 640 1462 T1080 1444 V1920 H0 Z" style="fill:color-mix(in srgb, var(--grass) 55%, var(--goldDeep))"/><g class="' + id + '-grass">' + grass + '</g>' +
      '<path d="M-40 1920 Q-30 1640 60 1590 Q150 1560 170 1650 Q200 1760 190 1920 Z" style="fill:var(--grass)"/></svg>' +
      '<div class="words" style="left:40px;right:40px;top:196px"><h1 class="head-line">Perfect line...!!</h1></div>';
  },
  // The puppet screen: cloth lit from behind, its weave, and the oil lamp's hot spot.
  cloth(id) {
    return '<defs><radialGradient id="' + id + '-lit" cx=".5" cy=".38" r=".75"><stop offset="0" style="stop-color:var(--second)"/><stop offset=".45" style="stop-color:var(--cloth)"/><stop offset="1" style="stop-color:var(--clothEdge)"/></radialGradient>' +
      '<pattern id="' + id + '-weave" width="9" height="9" patternUnits="userSpaceOnUse"><path d="M0 4.5 H9 M4.5 0 V9" style="stroke:var(--goldDeep);stroke-width:.6;opacity:.25"/></pattern></defs>' +
      '<rect width="918" height="1027" fill="url(#' + id + '-lit)"/><rect width="918" height="1027" fill="url(#' + id + '-weave)"/>';
  },
  lamp(id) {
    return '<circle class="' + id + '-lamp" cx="459" cy="360" r="380" style="fill:var(--second);opacity:.12"/>' +
      '<rect width="918" height="1027" style="fill:none;stroke:var(--redDeep);stroke-width:60;opacity:.35"/>';
  },
  // A court cut from leather, held back from the cloth so it falls soft: arches, pillars, lamps on chains.
  court(id) {
    let s = '<g class="' + id + '-court" style="opacity:.42">';
    for (const x of [40, 300, 618, 878]) s += '<rect x="' + (x - 26) + '" y="150" width="52" height="820" style="fill:var(--ink)"/><rect x="' + (x - 40) + '" y="130" width="80" height="34" style="fill:var(--ink)"/>' + W.lace(x, 220, x, 900, 12, 6);
    for (const [a, b] of [[40, 300], [300, 618], [618, 878]]) { const m = (a + b) / 2; s += '<path d="M' + a + ' 160 Q' + m + ' 30 ' + b + ' 160 L' + b + ' 130 Q' + m + ' 0 ' + a + ' 130 Z" style="fill:var(--ink)"/>' + '<path d="M' + m + ' 40 V210" style="stroke:var(--ink);stroke-width:3"/><path d="M' + (m - 26) + ' 210 H' + (m + 26) + ' L' + m + ' 250 Z" style="fill:var(--ink)"/>'; }
    return s + '<rect y="975" width="918" height="60" style="fill:var(--ink)"/></g>';
  },
  // Guards at the edge of the court: plain shadows, out of focus behind the cloth.
  guard(x, s, flip) {
    return '<g transform="translate(' + x + ' 975) scale(' + (flip ? -s : s) + ' ' + s + ')" style="fill:var(--ink);opacity:.35"><path d="M-30 0 L-22 -260 Q-40 -300 -30 -360 Q0 -400 28 -360 Q38 -300 22 -260 L30 0 Z"/><circle cx="0" cy="-400" r="34"/><path d="M-20 -436 L0 -490 L20 -436 Z"/><rect x="40" y="-620" width="8" height="620"/><path d="M32 -620 L44 -680 L56 -620 Z"/></g>';
  },
  // Subtitles, word by word, at the foot of the window.
  subs(kit, lines, st) {
    return {
      mk: '<div class="words" style="left:40px;right:40px;bottom:46px">' + lines.map((l) => '<p class="sub-line">' + kit.esc(l[2]) + '</p>').join('') + '</div>',
      bind(root) {
        this.ps = [...root.querySelectorAll('.sub-line')].map((p, i) => {
          const words = p.textContent.split(' ');
          p.innerHTML = words.map((w) => '<span>' + kit.esc(w) + '</span>').join(' ');
          return { p, sp: [...p.children], t0: lines[i][0] - st, t1: lines[i][1] - st, full: !!lines[i][3] };
        });
      },
      render(t) {
        for (const L of this.ps) {
          const on = t >= L.t0 - 0.05 && t <= L.t1 + 0.12;
          L.p.style.display = on ? '' : 'none';
          if (!on) continue;
          const n = L.sp.length, span = Math.max(0.3, (L.t1 - L.t0) * 0.7);
          L.sp.forEach((s, i) => { const k = L.full ? 1 : kit.clamp01((t - L.t0 - span * i / n) / 0.14); s.style.opacity = k; s.style.transform = 'translateY(' + ((1 - k) * 14).toFixed(1) + 'px)'; });
          L.p.style.opacity = kit.clamp01((L.t1 + 0.12 - t) / 0.12);
        }
      },
    };
  },
  // One shot: the reel frame, the lit cloth, the puppets on their rods, a slow push, talking jaws and subtitles.
  shot(kit, cfg) {
    const id = cfg.id, st = kit.start, dur = kit.dur;
    const cast = (cfg.cast || []).map((c, i) => '<g class="' + id + '-c' + i + '">' + W[c.who](id + '-' + c.who + i) + '</g>').join('');
    const subs = W.subs(kit, cfg.lines || [], st);
    const pic = '<svg class="art ' + id + '-pic" viewBox="0 0 918 1027">' + W.cloth(id) + '<g class="' + id + '-cam">' + (cfg.bg === 'court' ? W.court(id) : '') + (cfg.back || '') + cast + (cfg.front || '') + '</g>' + W.lamp(id) + '</svg>';
    kit.stage.append(kit.h('<div class="ground">' + W.frame(kit, id) + '<div class="pip">' + pic + subs.mk + '</div></div>'));
    const q = (s) => kit.stage.querySelector(s);
    const o = { cam: q('.' + id + '-cam'), lamp: q('.' + id + '-lamp'), sun: q('.' + id + '-sun'), grass: q('.' + id + '-grass'), parts: [] };
    (cfg.cast || []).forEach((c, i) => {
      const k = id + '-' + c.who + i;
      o.parts.push({ c, g: q('.' + id + '-c' + i), jaw: q('.' + k + '-jaw'), arm: q('.' + k + '-arm'), tear: q('.' + k + '-tear'), glow: q('.' + k + '-glow'), rig: W.RIG[c.who] || { jaw: [0, 0], arm: [0, 0] } });
    });
    subs.bind(kit.stage);
    const lines = (cfg.lines || []).map((l) => [l[0] - st, l[1] - st, l[4] ?? 0]);
    return {
      render(t) {
        const p = kit.eio(kit.clamp01(t / dur)), c = cfg.cam || [1, 1.03, 459, 513, 459, 513];
        const z = kit.lerp(c[0], c[1], p), cx = kit.lerp(c[2], c[4] ?? c[2], p), cy = kit.lerp(c[3], c[5] ?? c[3], p);
        o.cam.setAttribute('transform', 'translate(459 513) scale(' + z.toFixed(4) + ') translate(' + (-cx).toFixed(1) + ' ' + (-cy).toFixed(1) + ')');
        o.lamp.style.opacity = (0.12 + 0.03 * Math.sin(t * 1.9) + 0.02 * Math.sin(t * 3.1)).toFixed(3);
        o.sun.style.opacity = (0.85 + 0.1 * Math.sin(t * 0.7)).toFixed(3);
        o.grass.setAttribute('transform', 'skewX(' + (1.2 * Math.sin(t * 0.9)).toFixed(2) + ')');
        o.parts.forEach((pt, i) => {
          const { c: cc, rig } = pt, sway = 0.9 * Math.sin(t * 1.25 + i * 2), bob = 3 * Math.sin(t * 1.7 + i);
          pt.g.setAttribute('transform', 'translate(' + cc.x + ' ' + (cc.y + bob).toFixed(1) + ') rotate(' + sway.toFixed(2) + ') scale(' + (cc.flip ? -cc.s : cc.s) + ' ' + cc.s + ')');
          const talk = lines.some((l) => l[2] === i && t >= l[0] && t <= l[1]);
          const v = kit.vnoise(31 + i)(t * 2.2) * 0.5 + 0.5;
          if (pt.jaw) pt.jaw.setAttribute('transform', 'rotate(' + (talk ? (2 + 7 * v * (0.5 + 0.5 * Math.sin(t * 17))) : 0).toFixed(2) + ' ' + rig.jaw[0] + ' ' + rig.jaw[1] + ')');
          const arm = cfg.arm ? cfg.arm(t, i, talk) : (talk ? -6 + 8 * Math.sin(t * 1.6 + i) : 2 * Math.sin(t * 0.8 + i));
          if (pt.arm) pt.arm.setAttribute('transform', 'rotate(' + arm.toFixed(2) + ' ' + rig.arm[0] + ' ' + rig.arm[1] + ')');
          if (pt.tear) { const k = ((t * 0.45) % 1 + 1) % 1; pt.tear.style.opacity = cfg.tears ? (k < 0.8 ? 1 : (1 - k) * 5).toFixed(2) : 0; pt.tear.setAttribute('transform', 'translate(0 ' + (k * 36).toFixed(1) + ')'); }
          if (pt.glow) pt.glow.style.opacity = cfg.glow ? (0.45 + 0.25 * Math.sin(t * 2.1)).toFixed(3) : 0;
        });
        subs.render(t);
        if (cfg.extra) cfg.extra(t, kit.stage);
      },
    };
  },
};
